INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("The Mutable Default Trap", "py-mutable-default-trap", "python", "easy", 1, "logical", "The function `add_item` is supposed to append an item to a list and return it. However, when called multiple times without providing a list, previously added items unexpectedly persist!", "def add_item(item, shopping_list=[]):\n    shopping_list.append(item)\n    return shopping_list\n\n# Test calls\nprint(add_item('apples'))\nprint(add_item('oranges'))  # BUG: outputs ['apples', 'oranges'] instead of ['oranges']", "def add_item(item, shopping_list=None):\n    if shopping_list is None:\n        shopping_list = []\n    shopping_list.append(item)\n    return shopping_list\n\n# Test calls\nprint(add_item('apples'))\nprint(add_item('oranges'))", "Unexpected Output:\n['apples']\n['apples', 'oranges']  <-- Expected: ['oranges'] for second call", "When `shopping_list` is not passed in the second call, it should start with a fresh empty list `['oranges']`.", "In Python, default arguments are evaluated only once when the function is defined, not every time it is called.", "Using a mutable object like a list `[]` as a default parameter causes state to be shared across calls.", "Change default to `shopping_list=None` and initialize `if shopping_list is None: shopping_list = []` inside the function.", "Python default argument expressions are evaluated once at function definition time, making mutable defaults (like `[]` or `{}`) shared across all invocations.", "Because `shopping_list=[]` is instantiated only once when Python compiles the function header, every call that relies on the default parameter mutates the same list object in memory.", "Use `None` as the sentinel default value and instantiate a new empty list inside the function body whenever the parameter is `None`.", "{\"must_contain\":[\"shopping_list=None\",\"if shopping_list is None\",\"shopping_list = []\"],\"must_not_contain\":[\"shopping_list=[]\"]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Missing Dictionary Key Crash", "py-keyerror-crash", "python", "easy", 1, "runtime", "The profile processing script crashes with a `KeyError` when an optional field `vip_status` is missing from the customer data.", "def is_vip_customer(customer):\n    # Crashes if customer dictionary has no 'vip_status' key\n    if customer['vip_status'] == True:\n        return 'VIP Member'\n    return 'Regular Customer'\n\nuser = {'name': 'Alice', 'orders': 3}\nprint(is_vip_customer(user))", "def is_vip_customer(customer):\n    # Safely checks optional key\n    if customer.get('vip_status', False) == True:\n        return 'VIP Member'\n    return 'Regular Customer'\n\nuser = {'name': 'Alice', 'orders': 3}\nprint(is_vip_customer(user))", "Traceback (most recent call last):\n  File \"solution.py\", line 3, in is_vip_customer\n    if customer['vip_status'] == True:\nKeyError: 'vip_status'", "Safely handle customer records that may not have the 'vip_status' key, defaulting to False\/Regular Customer without crashing.", "Direct square-bracket index access `dict[key]` raises KeyError if the key is missing.", "The dictionary method `.get(key, default)` safely returns a fallback value if the key does not exist.", "Replace `customer['vip_status']` with `customer.get('vip_status', False)`.", "Accessing a non-existent key in a Python dict with square bracket notation raises an unhandled `KeyError` exception.", "Python dictionaries do not return `None` or falsey values automatically when indexing missing keys; they raise an exception to prevent silent data issues.", "Use `customer.get('vip_status', False)` which returns the specified default value without raising an exception.", "{\"must_contain\":[\".get('vip_status'\"],\"must_not_contain\":[\"customer['vip_status']\"]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Infinite Recursion Stack Overflow", "py-infinite-recursion", "python", "medium", 2, "runtime", "The recursive function `countdown_timer` is supposed to count down from `n` to `1` and then print \"Blast off!\", but instead it crashes the interpreter.", "def countdown_timer(n):\n    print(n)\n    # BUG: missing base condition\n    countdown_timer(n - 1)\n\ncountdown_timer(5)", "def countdown_timer(n):\n    if n <= 0:\n        print(\"Blast off!\")\n        return\n    print(n)\n    countdown_timer(n - 1)\n\ncountdown_timer(5)", "RecursionError: maximum recursion depth exceeded while calling a Python object", "Count down numbers 5, 4, 3, 2, 1 and terminate gracefully with 'Blast off!'.", "Every recursive function requires a terminating condition known as a base case.", "Without checking if `n <= 0`, the function will recurse infinitely into negative numbers until Python hits its stack limit.", "Add `if n <= 0: return` or print and return before the recursive call.", "The recursive function lacks a base case, causing it to call itself endlessly until the call stack overflows.", "Each recursive invocation pushes a frame onto the call stack. Without a stopping condition, the maximum recursion depth (default 1000 in Python) is exceeded.", "Add an explicit base case `if n <= 0:` that prints the terminal message and returns immediately.", "{\"must_contain\":[\"n <= 0\",\"return\"],\"must_not_contain\":[]}", 120) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Var Scoping in Asynchronous Loop", "js-var-scoping-async-loop", "javascript", "easy", 1, "scoping", "The developer created a loop to print delayed numbers 0, 1, 2. Instead, the console prints `3, 3, 3`!", "for (var i = 0; i < 3; i++) {\n    setTimeout(() => {\n        console.log(\"Timer value:\", i);\n    }, 100);\n}", "for (let i = 0; i < 3; i++) {\n    setTimeout(() => {\n        console.log(\"Timer value:\", i);\n    }, 100);\n}", "Actual Output:\nTimer value: 3\nTimer value: 3\nTimer value: 3\nExpected Output:\nTimer value: 0\nTimer value: 1\nTimer value: 2", "Each timer callback should capture its own iteration number (0, 1, 2).", "Notice the declaration keyword used for `i` in the `for` loop.", "`var` is function-scoped (or globally scoped), meaning all timer callbacks share the exact same variable `i`.", "Use `let` which provides block-scoping so each loop iteration creates a new binding for `i`.", "Using `var` creates a single shared variable across all loop iterations. When callbacks execute, `i` has already incremented to 3.", "`var` does not create a block scope inside the loop. By the time `setTimeout` callbacks run asynchronously, the loop has completed and `i` equals 3.", "Replace `var i = 0` with `let i = 0`. In ES6, `let` in a for-loop creates a new binding for each iteration.", "{\"must_contain\":[\"for (let i = 0;\",\"console.log\"],\"must_not_contain\":[\"for (var i = 0;\"]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Cannot Read Properties of Undefined", "js-cannot-read-property-null", "javascript", "easy", 1, "runtime", "A helper function retrieves the user's city from a nested profile object. When a user has no address set, the application throws an uncaught TypeError.", "function getUserCity(user) {\n    \/\/ Crashes when user.profile or address is missing\n    return user.profile.address.city;\n}\n\nconst guest = { id: 101, profile: null };\nconsole.log(getUserCity(guest));", "function getUserCity(user) {\n    \/\/ Uses optional chaining to prevent crash\n    return user?.profile?.address?.city || 'Unknown';\n}\n\nconst guest = { id: 101, profile: null };\nconsole.log(getUserCity(guest));", "TypeError: Cannot read properties of null (reading 'address')\n    at getUserCity (index.js:3:25)", "Safely return the city if available, or a fallback string without throwing a runtime error.", "Accessing nested properties on `null` or `undefined` throws a fatal TypeError in JavaScript.", "Modern JavaScript provides the Optional Chaining operator `?.` to safely access deep object properties.", "Use `user?.profile?.address?.city` or an `if` check to guard against null.", "Accessing property `.address` on `user.profile` when `profile` is `null` causes JavaScript to throw a TypeError.", "JavaScript cannot dereference properties on primitive null or undefined values, crashing the execution stack.", "Use optional chaining (`?.`) like `user?.profile?.address?.city` to safely return undefined\/fallback if any link in the chain is nullish.", "{\"must_contain\":[\"user?.profile?.address?.city\"],\"must_not_contain\":[\"user.profile.address.city\"]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("String Concatenation Arithmetic Mistake", "js-type-coercion-addition", "javascript", "medium", 2, "type_error", "The shopping cart calculates total order price by adding product price and shipping cost. Instead of $120, it displays $10020!", "function calculateTotal(priceInput, shippingCost) {\n    \/\/ priceInput comes from an HTML input field as a string\n    const total = priceInput + shippingCost;\n    return \"$\" + total;\n}\n\n\/\/ priceInput: \"100\", shipping: 20\nconsole.log(calculateTotal(\"100\", 20)); \/\/ Output: $10020", "function calculateTotal(priceInput, shippingCost) {\n    \/\/ Parse priceInput as a number\n    const total = Number(priceInput) + shippingCost;\n    return \"$\" + total;\n}\n\n\/\/ priceInput: \"100\", shipping: 20\nconsole.log(calculateTotal(\"100\", 20)); \/\/ Output: $120", "Output: \"$10020\"\nExpected: \"$120\"", "Perform numerical addition rather than string concatenation, producing $120.", "The `+` operator in JavaScript performs string concatenation if either operand is a string.", "`priceInput` is a string `\"100\"`, so `\"100\" + 20` results in `\"10020\"`.", "Convert `priceInput` to a number using `Number(priceInput)` or `parseFloat(priceInput)` before adding.", "The `+` operator overloaded behavior coerced the number `20` to string `\"20\"` and concatenated them into `\"10020\"`.", "In JavaScript, if any operand of the binary `+` operator is a string, JavaScript converts the other operand to a string as well.", "Explicitly convert the string operand to a number using `Number(priceInput)` or `parseFloat()` before the addition.", "{\"must_contain\":[\"Number(priceInput)\",\"parseFloat(priceInput)\"],\"must_not_contain\":[\"const total = priceInput + shippingCost\"]}", 110) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Missing Address-Of Operator in Scanf", "c-scanf-missing-ampersand", "c", "easy", 1, "runtime", "The program crashes with a Segmentation Fault immediately upon user input in `scanf`.", "#include <stdio.h>\n\nint main() {\n    int age;\n    printf(\"Enter your age: \");\n    \/\/ BUG: Missing '&' before age\n    scanf(\"%d\", age);\n    printf(\"You are %d years old.\\n\", age);\n    return 0;\n}", "#include <stdio.h>\n\nint main() {\n    int age;\n    printf(\"Enter your age: \");\n    \/\/ Fixed with &age\n    scanf(\"%d\", &age);\n    printf(\"You are %d years old.\\n\", age);\n    return 0;\n}", "Segmentation fault (core dumped)\nWarning: format '%d' expects argument of type 'int *', but argument 2 has type 'int'", "Store user input correctly into the `age` variable without crashing.", "`scanf` requires memory addresses of variables so it knows where to write the input.", "Passing `age` by value gives `scanf` whatever random number was in `age` as an address, causing an invalid memory access.", "Use the address-of operator `&age` in `scanf(\"%d\", &age)`.", "Passing `age` instead of `&age` to `scanf` provides an invalid memory address for writing input.", "`scanf` requires pointers (`int *`) to store scanned data. Passing an uninitialized `int` by value causes `scanf` to treat that value as an address in memory and write to it, triggering a SIGSEGV.", "Pass the address of the variable using `&age`.", "{\"must_contain\":[\"scanf(\\\"%d\\\", &age);\"],\"must_not_contain\":[\"scanf(\\\"%d\\\", age);\"]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Dangling Pointer & Local Stack Memory", "c-dangling-pointer-stack-return", "c", "hard", 3, "memory", "A helper function attempts to initialize and return an array of integers, but reading the array in `main` produces garbage data or segmentation fault.", "#include <stdio.h>\n\nint* get_scores() {\n    int scores[3] = {95, 88, 72};\n    \/\/ BUG: Returning address of local stack variable\n    return scores;\n}\n\nint main() {\n    int* my_scores = get_scores();\n    printf(\"First score: %d\\n\", my_scores[0]);\n    return 0;\n}", "#include <stdio.h>\n#include <stdlib.h>\n\nint* get_scores() {\n    int* scores = (int*)malloc(3 * sizeof(int));\n    scores[0] = 95;\n    scores[1] = 88;\n    scores[2] = 72;\n    return scores;\n}\n\nint main() {\n    int* my_scores = get_scores();\n    printf(\"First score: %d\\n\", my_scores[0]);\n    free(my_scores);\n    return 0;\n}", "Warning: function returns address of local variable [-Wreturn-local-addr]\nOutput: First score: 0 (or random garbage)", "Dynamically allocate heap memory so the array remains valid after function exit.", "Local arrays declared on the stack are deallocated the moment the function returns.", "The pointer returned becomes a dangling pointer pointing to reclaimed stack memory.", "Allocate the memory on the heap using `malloc(3 * sizeof(int))` and free it in `main`.", "Returning the address of a local automatic stack array causes undefined behavior because its stack frame is discarded upon return.", "Stack memory is scoped strictly to the function call. Once `get_scores()` finishes, `scores` is invalid.", "Allocate memory on the heap with `malloc(3 * sizeof(int))` and ensure it is freed with `free()` when done.", "{\"must_contain\":[\"malloc(\",\"free(\"],\"must_not_contain\":[\"int scores[3] = {95, 88, 72};\"]}", 150) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Missing Virtual Destructor in Base Class", "cpp-missing-virtual-destructor", "cpp", "medium", 2, "memory", "When deleting a derived object via a base class pointer, the derived destructor is never invoked, causing a silent memory leak.", "#include <iostream>\n\nclass Base {\npublic:\n    Base() { std::cout << \"Base created\\n\"; }\n    \/\/ BUG: Destructor is not virtual!\n    ~Base() { std::cout << \"Base destroyed\\n\"; }\n};\n\nclass Derived : public Base {\n    int* buffer;\npublic:\n    Derived() { buffer = new int[100]; std::cout << \"Derived allocated\\n\"; }\n    ~Derived() { delete[] buffer; std::cout << \"Derived cleaned up\\n\"; }\n};\n\nint main() {\n    Base* ptr = new Derived();\n    delete ptr; \/\/ Never calls Derived destructor!\n    return 0;\n}", "#include <iostream>\n\nclass Base {\npublic:\n    Base() { std::cout << \"Base created\\n\"; }\n    \/\/ Virtual destructor ensures polymorphic cleanup\n    virtual ~Base() { std::cout << \"Base destroyed\\n\"; }\n};\n\nclass Derived : public Base {\n    int* buffer;\npublic:\n    Derived() { buffer = new int[100]; std::cout << \"Derived allocated\\n\"; }\n    ~Derived() { delete[] buffer; std::cout << \"Derived cleaned up\\n\"; }\n};\n\nint main() {\n    Base* ptr = new Derived();\n    delete ptr;\n    return 0;\n}", "Output:\nBase created\nDerived allocated\nBase destroyed\n(Note: 'Derived cleaned up' is NEVER printed, buffer is leaked!)", "Both Derived and Base destructors should execute upon deletion, properly releasing `buffer`.", "Polymorphism in C++ requires virtual dispatch for destructors when deleting through a base class pointer.", "Without `virtual`, the compiler statically binds `delete ptr` to `~Base()` only.", "Prefix `~Base()` with the `virtual` keyword.", "Deleting a derived object through a base pointer with a non-virtual destructor results in undefined behavior and skips the derived class destructor.", "Without `virtual`, C++ performs static binding at compile time based on the pointer type (`Base*`), bypassing dynamic dispatch in the vtable.", "Declare `virtual ~Base()` in the base class to guarantee full polymorphic destruction.", "{\"must_contain\":[\"virtual ~Base()\"],\"must_not_contain\":[\"    ~Base() {\"]}", 120) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Vector Iterator Invalidation During Erase", "cpp-iterator-invalidation-erase", "cpp", "hard", 3, "runtime", "The loop is intended to remove all even numbers from a `std::vector`, but it crashes or skips elements due to iterator invalidation.", "#include <iostream>\n#include <vector>\n\nint main() {\n    std::vector<int> nums = {1, 2, 4, 5, 6};\n    for (auto it = nums.begin(); it != nums.end(); ++it) {\n        if (*it % 2 == 0) {\n            \/\/ BUG: erase invalidates 'it', and ++it causes undefined behavior!\n            nums.erase(it);\n        }\n    }\n    return 0;\n}", "#include <iostream>\n#include <vector>\n\nint main() {\n    std::vector<int> nums = {1, 2, 4, 5, 6};\n    for (auto it = nums.begin(); it != nums.end(); ) {\n        if (*it % 2 == 0) {\n            it = nums.erase(it);\n        } else {\n            ++it;\n        }\n    }\n    return 0;\n}", "Runtime Error: vector iterator not incrementable \/ Segmentation Fault", "Erase even numbers safely without crashing or skipping consecutive even values.", "`nums.erase(it)` invalidates the iterator `it` and all subsequent iterators.", "`erase()` returns a new valid iterator pointing to the element immediately following the removed one.", "Assign `it = nums.erase(it)` and only advance `++it` when no element was removed.", "`std::vector::erase` invalidates iterators at and after the erased element, making subsequent `++it` undefined behavior.", "When an element is erased from a vector, remaining elements are shifted down. The original iterator is invalidated.", "Capture the return value of `erase()` with `it = nums.erase(it)` and only perform `++it` in the `else` branch.", "{\"must_contain\":[\"it = nums.erase(it);\",\"} else {\",\"++it;\"],\"must_not_contain\":[\"for (auto it = nums.begin(); it != nums.end(); ++it)\"]}", 150) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("String Equality with == vs .equals()", "java-string-equality-double-equals", "java", "easy", 1, "logical", "The authentication check fails even when the user enters the exact correct password \"secret123\".", "public class AuthCheck {\n    public static boolean checkPassword(String inputPassword) {\n        String actualPassword = new String(\"secret123\");\n        \/\/ BUG: Comparing object references with ==\n        if (inputPassword == actualPassword) {\n            return true;\n        }\n        return false;\n    }\n    \n    public static void main(String[] args) {\n        System.out.println(checkPassword(new String(\"secret123\"))); \/\/ prints false!\n    }\n}", "public class AuthCheck {\n    public static boolean checkPassword(String inputPassword) {\n        String actualPassword = new String(\"secret123\");\n        \/\/ Use .equals() for content comparison\n        if (actualPassword.equals(inputPassword)) {\n            return true;\n        }\n        return false;\n    }\n    \n    public static void main(String[] args) {\n        System.out.println(checkPassword(new String(\"secret123\")));\n    }\n}", "Output: false\nExpected: true", "Accurately verify that the string contents match, returning true.", "In Java, `==` tests object reference equality (memory location), not value equality.", "Two distinct String objects can contain the exact same characters while being different instances in memory.", "Use `.equals()` to compare the character contents of Strings in Java.", "Comparing String objects using `==` checks whether both references point to the exact same memory address rather than comparing their text contents.", "Objects created with `new String(...)` exist in different heap locations. `==` compares pointer addresses, which are distinct.", "Use `actualPassword.equals(inputPassword)` to compare string character sequences.", "{\"must_contain\":[\".equals(\"],\"must_not_contain\":[\"inputPassword == actualPassword\"]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("NullPointerException in Auto-Unboxing", "java-npe-auto-unboxing", "java", "medium", 2, "runtime", "The inventory calculator crashes with a `NullPointerException` when processing an item whose stock quantity is unset (`null`).", "public class StockCalculator {\n    public static int calculateTotal(Integer currentStock, int shipment) {\n        \/\/ BUG: currentStock can be null; unboxing to int throws NPE\n        int total = currentStock + shipment;\n        return total;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(calculateTotal(null, 25));\n    }\n}", "public class StockCalculator {\n    public static int calculateTotal(Integer currentStock, int shipment) {\n        int baseStock = (currentStock != null) ? currentStock : 0;\n        int total = baseStock + shipment;\n        return total;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(calculateTotal(null, 25));\n    }\n}", "Exception in thread \"main\" java.lang.NullPointerException: Cannot invoke \"java.lang.Integer.intValue()\" because \"currentStock\" is null\n\tat StockCalculator.calculateTotal(StockCalculator.java:4)", "Treat a null `currentStock` as 0 and return 25 without throwing an exception.", "When Java performs arithmetic between a wrapper `Integer` and a primitive `int`, it secretly invokes `currentStock.intValue()`.", "If `currentStock` is `null`, invoking `intValue()` throws a NullPointerException.", "Check if `currentStock == null` and provide a fallback (e.g. 0) before performing the addition.", "Implicit unboxing of a null `Integer` wrapper into primitive `int` triggers an automatic `.intValue()` call on null.", "Java compilers automatically insert `.intValue()` during arithmetic operations on boxed types. Calling any method on null causes a NullPointerException.", "Explicitly check for `currentStock != null ? currentStock : 0` before adding to primitive `shipment`.", "{\"must_contain\":[\"currentStock != null\",\": 0\"],\"must_not_contain\":[\"int total = currentStock + shipment;\"]}", 120) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("SQL Injection Vulnerability via Direct Concatenation", "php-sql-injection-prepared-statements", "php", "easy", 1, "database", "The login handler directly concatenates user input into an SQL query string, creating a critical SQL injection flaw and syntax failure on quotes.", "<?php\nfunction authenticateUser($pdo, $email, $password) {\n    \/\/ BUG: Direct concatenation leads to SQL injection!\n    $sql = \"SELECT id, name FROM users WHERE email = '$email' AND password = '$password'\";\n    $result = $pdo->query($sql);\n    return $result->fetch();\n}", "<?php\nfunction authenticateUser($pdo, $email, $password) {\n    \/\/ Use prepared statements with parameterized inputs\n    $stmt = $pdo->prepare(\"SELECT id, name FROM users WHERE email = :email AND password = :password\");\n    $stmt->execute([\n        ':email' => $email,\n        ':password' => $password\n    ]);\n    return $stmt->fetch();\n}", "Security Audit Alert: CRITICAL SQL INJECTION (CWE-89)\nSyntax Error when email contains single quotes e.g. o'connor@test.com", "Use parameterized prepared statements with PDO to safely escape and execute queries.", "Never interpolate raw variables directly into SQL queries.", "PDO provides $pdo->prepare(...) and $stmt->execute(...).", "Replace the raw string with named parameters (:email, :password) and pass an array to execute().", "String interpolation in SQL allows untrusted input to break out of data context into code execution context, enabling attackers to bypass authentication or steal data.", "Without parameterization, characters like ' terminate the SQL string literal, allowing arbitrary SQL commands to be injected.", "Use PDO prepared statements with parameter placeholders (:email) so that the database engine parses the query structure separately from the data values.", "{\"must_contain\":[\"$pdo->prepare\",\"$stmt->execute\",\":email\"],\"must_not_contain\":[\"$pdo->query($sql)\"]}", 110) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Strict In_Array Type Comparison Bug", "php-in-array-loose-comparison", "php", "medium", 2, "logical", "A security gate checks if an entered authorization code matches any prohibited keys. Because of loose comparison, unexpected access is granted.", "<?php\nfunction isBannedUser($userId, $bannedList) {\n    \/\/ BUG: in_array defaults to loose comparison (==)\n    \/\/ When $userId is 0 or true, string conversions can match incorrectly!\n    if (in_array($userId, $bannedList)) {\n        return true;\n    }\n    return false;\n}\n\n$banned = [\"admin_lock\", \"banned_flag\"];\n\/\/ In PHP 7\/8 loose comparison, 0 == \"admin_lock\" evaluates true in older runtimes\necho isBannedUser(0, $banned) ? \"Banned\" : \"Allowed\";", "<?php\nfunction isBannedUser($userId, $bannedList) {\n    \/\/ Enable strict comparison (===) via third argument true\n    if (in_array($userId, $bannedList, true)) {\n        return true;\n    }\n    return false;\n}\n\n$banned = [\"admin_lock\", \"banned_flag\"];\necho isBannedUser(0, $banned) ? \"Banned\" : \"Allowed\";", "Unexpected Result: Evaluated as matching due to loose type coercion in array lookup.", "Enforce strict type checking so integers never loosely match arbitrary strings.", "`in_array` takes an optional third argument $strict.", "By default, `in_array` uses loose comparison == instead of ===.", "Pass true as the third parameter: in_array($userId, $bannedList, true).", "Default `in_array()` uses loose comparison (`==`), which allows type juggling between numbers, booleans, and strings.", "Without strict checking, PHP coerces data types, causing subtle and critical security bypasses.", "Always pass `true` as the third argument to `in_array($needle, $haystack, true)` for strict `===` comparison.", "{\"must_contain\":[\"in_array($userId, $bannedList, true)\"],\"must_not_contain\":[\"in_array($userId, $bannedList)\"]}", 120) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("The Three-Valued Logic NULL Trap", "sql-null-comparison-is-null", "sql", "easy", 1, "database", "The HR manager wants a list of all employees who have NOT been assigned a bonus yet. The query runs with 0 errors but unexpectedly returns 0 rows!", "-- BUG: Comparing with = NULL always yields UNKNOWN (false)\nSELECT employee_id, first_name, salary\nFROM employees\nWHERE bonus = NULL;", "-- Use IS NULL for three-valued relational logic\nSELECT employee_id, first_name, salary\nFROM employees\nWHERE bonus IS NULL;", "Returned: 0 rows\nExpected: 14 employees who have no bonus recorded in the database.", "Return all employees whose `bonus` column contains NULL.", "In ANSI SQL, `NULL` represents the absence of a value, not a specific value.", "Any comparison using `= NULL` evaluates to `UNKNOWN`, which is treated as false in WHERE filters.", "Replace `= NULL` with `IS NULL`.", "In SQL three-valued logic (TRUE, FALSE, UNKNOWN), `bonus = NULL` evaluates to `UNKNOWN` for every single row, causing all rows to be filtered out.", "NULL cannot be equal to anything, not even another NULL. Therefore, the equality operator `=` can never return TRUE when comparing against NULL.", "Use the `IS NULL` predicate instead of `= NULL`.", "{\"must_contain\":[\"WHERE bonus IS NULL\"],\"must_not_contain\":[\"bonus = NULL\"]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Missing Column in GROUP BY Aggregation", "sql-missing-group-by-column", "sql", "medium", 2, "database", "The analytics dashboard query fails to calculate average revenue per department and year.", "-- BUG: 'fiscal_year' is selected but not included in GROUP BY\nSELECT department, fiscal_year, AVG(revenue) AS avg_rev\nFROM quarterly_reports\nGROUP BY department;", "-- Include all non-aggregated columns in GROUP BY\nSELECT department, fiscal_year, AVG(revenue) AS avg_rev\nFROM quarterly_reports\nGROUP BY department, fiscal_year;", "ERROR 1055 (42000): 'quarterly_reports.fiscal_year' isn't in GROUP BY clause and contains nonaggregated column which is not functionally dependent on columns in GROUP BY clause (ONLY_FULL_GROUP_BY)", "Group records properly by both department and fiscal_year to satisfy SQL aggregation standards.", "Every column in the `SELECT` list that is not part of an aggregate function (like `AVG`, `SUM`, `COUNT`) must appear in the `GROUP BY` clause.", "`fiscal_year` is selected directly without an aggregate wrapper.", "Update the `GROUP BY` clause to: `GROUP BY department, fiscal_year;`.", "Selecting a non-aggregated column (`fiscal_year`) that is not listed in `GROUP BY` violates SQL standards and fails in modern SQL modes (ONLY_FULL_GROUP_BY).", "Without grouping by `fiscal_year`, SQL has no way to know which fiscal year value to display for each department group.", "Add `fiscal_year` into the `GROUP BY` statement: `GROUP BY department, fiscal_year`.", "{\"must_contain\":[\"GROUP BY department, fiscal_year\"],\"must_not_contain\":[\"GROUP BY department;\"]}", 110) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("CSS Box Sizing Width Overflow", "html-css-box-sizing-overflow", "html-css", "easy", 1, "ui", "A modal dialog card with `width: 100%` and `padding: 24px` overflows horizontally beyond its parent screen container, causing ugly horizontal scrollbars.", ".modal-container {\n    width: 100%;\n    padding: 24px;\n    border: 2px solid #3b82f6;\n    \/* BUG: default content-box causes width to be 100% + 48px + 4px! *\/\n    background: #1e293b;\n}", ".modal-container {\n    box-sizing: border-box;\n    width: 100%;\n    padding: 24px;\n    border: 2px solid #3b82f6;\n    background: #1e293b;\n}", "UI Render Flaw: Horizontal scrollbar appears. Computed element width is 100% + 52px of padding and borders.", "Keep the entire card within 100% of parent width including its padding and borders.", "By default in CSS, `box-sizing` is set to `content-box`.", "With `content-box`, `padding` and `border` are added ON TOP of the specified `width: 100%`.", "Add `box-sizing: border-box;` to include padding and borders inside the specified width.", "Default CSS box model (`content-box`) adds padding and border outside the specified width, exceeding 100% of the parent width.", "Total width = content width (100%) + padding-left (24px) + padding-right (24px) + borders (4px).", "Set `box-sizing: border-box;` so padding and borders are factored into the element's total declared width.", "{\"must_contain\":[\"box-sizing: border-box;\"],\"must_not_contain\":[]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO challenges (title, slug, language_slug, difficulty, level_tier, bug_type, description, broken_code, solution_code, error_output, expected_behavior, hint1, hint2, hint3, explanation_bug, explanation_why, explanation_fix, verification_rules, xp_reward) VALUES ("Broken Flexbox Centering & Stretched Items", "html-css-flexbox-centering", "html-css", "easy", 1, "ui", "The developer wanted to center a login card both horizontally and vertically inside a full-height hero section, but the card is glued to the top-left.", ".hero-section {\n    display: flex;\n    height: 100vh;\n    \/* BUG: missing horizontal and vertical centering properties *\/\n}", ".hero-section {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 100vh;\n}", "UI Render Flaw: Child item is positioned at top-left instead of the exact center of the screen.", "Center child elements horizontally and vertically within the 100vh container.", "`display: flex` by default aligns items along the start of the main axis.", "Horizontal alignment along the main axis is controlled by `justify-content`.", "Add `justify-content: center;` and `align-items: center;`.", "The flex container lacked the cross-axis (`align-items`) and main-axis (`justify-content`) alignment declarations.", "Without alignment rules, Flexbox defaults to `justify-content: flex-start` and `align-items: stretch`.", "Add `justify-content: center;` and `align-items: center;` to the flex container.", "{\"must_contain\":[\"justify-content: center;\",\"align-items: center;\"],\"must_not_contain\":[]}", 100) ON DUPLICATE KEY UPDATE title=VALUES(title);
